/**
 * Major reasoning category
 */
export type ReasoningCategory =
  | "deductive"
  | "inductive"
  | "abductive"
  | "analogical"
  | "causal"
  | "mathematical"
  | "scientific"
  | "probabilistic"
  | "dialectical"
  | "practical"
  | "creative"
  | "critical";

/**
 * Reasoning type definition
 */
export interface ReasoningType {
  id: string;
  name: string;
  category: ReasoningCategory;
  description: string;
  aliases: string[];
  relatedTypes: string[]; // IDs of related reasoning types
  prerequisites: string[]; // IDs of prerequisite types
  applications: string[];
  strengths: string[];
  limitations: string[];
  examples: string[];
  keywords: string[];
  difficulty: "beginner" | "intermediate" | "advanced" | "expert";
  usageFrequency: "rare" | "uncommon" | "common" | "very_common";
  formalDefinition?: string;
  notation?: string;
}

